#include "stock_native_bot_python.hpp"
#include "stock_native_client_state.hpp"
#include "../room/room_value.hpp"
namespace cs=stock_native_client_state;
namespace room=wot::room;
namespace {
cs::Value pose(const cs::Pose&value){auto out=room::array();for(double n:value)out.array.push_back(room::number(n));return out;}
cs::Value optional(const std::optional<std::int64_t>&value){return value?room::integer(*value):cs::Value{};}
cs::Value events(const std::vector<cs::Event>&value){auto out=room::array();for(const auto&e:value)out.array.push_back(e.payload);return out;}
cs::Value inspect(const cs::State&state){auto out=room::object();out.object["round"]=state.round;out.object["sequence"]=optional(state.sequence);out.object["bot_revision"]=optional(state.bot_revision);out.object["motion_time"]=optional(state.motion_time);out.object["bot_time"]=optional(state.bot_time);out.object["order_revision"]=optional(state.order_revision);out.object["server_time_ms"]=optional(state.server_time_ms);out.object["phase"]=room::text(state.timing_phase);out.object["reset_pending"]=room::boolean(state.reset_pending);out.object["actors"]=room::object();for(const auto&[key,actor]:state.actors){const auto&a=*actor;auto row=room::object();row.object["id"]=room::integer(a.id);row.object["state"]=a.state;row.object["manifest"]=a.manifest;row.object["dead"]=room::boolean(a.dead);row.object["missing"]=room::boolean(a.missing);row.object["current"]=pose(a.current);row.object["target"]=pose(a.target);row.object["samples"]=room::integer(static_cast<std::int64_t>(a.samples.size()));row.object["receipts"]=room::integer(static_cast<std::int64_t>(a.receipts.size()));row.object["sample_revision"]=optional(a.sample_revision);row.object["observed"]=room::number(a.observed);row.object["ideal"]=room::number(a.ideal);row.object["delay"]=room::number(a.delay);row.object["sample_time"]=room::number(a.sample_time);row.object["anchor_time"]=room::number(a.anchor_time);out.object["actors"].object[key]=std::move(row);}return out;}
cs::Value forward(const cs::Value&value,int mode){if(!mode)return value;const auto owner=room::freeze(value);if(mode==1)return room::objectView(owner);auto view=room::object();for(const auto&field:owner->resolved().object){cs::Value reference;reference.kind=cs::Value::Kind::Shared;reference.reference=std::shared_ptr<const cs::Value>(owner,&field.second);view.object.emplace(field.first,std::move(reference));}return view;}
PyObject* replay(PyObject*,PyObject*args){PyObject*raw_manifest=nullptr,*raw_snapshots=nullptr;int shared=0;if(!PyArg_ParseTuple(args,"OOi",&raw_manifest,&raw_snapshots,&shared))return nullptr;try{cs::State state;const auto manifest=cs::read(raw_manifest),snapshots=cs::read(raw_snapshots);auto out=room::array();auto admit_manifest=[&](const cs::Value&value){const auto admitted=cs::manifest(state,forward(value,shared));auto first=inspect(state);first.object["events"]=events(admitted);out.array.push_back(std::move(first));};if(manifest.resolved().kind==cs::Value::Kind::Array)for(const auto&value:room::rows(manifest))admit_manifest(value);else admit_manifest(manifest);double now=1.;for(const auto&snapshot:room::rows(snapshots)){const auto admitted=cs::snapshot(state,forward(snapshot,shared),now);now+=.05;auto row=inspect(state);row.object["events"]=events(admitted);out.array.push_back(std::move(row));}return cs::write(out);}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_RuntimeError,e.what());return nullptr;}}
PyMethodDef methods[]={{"replay",replay,METH_VARARGS,nullptr},{nullptr,nullptr,0,nullptr}};
}
extern "C" PyMODINIT_FUNC initclient_state_shared_test(){Py_InitModule("client_state_shared_test",methods);}
